/** Return ring entries with seq > afterSeq, or null if the gap is unresolvable. */
getSeqRingFrom(id: string, afterSeq: number): null | readonly SeqRingEntry[] {
  const terminal = this.terminals.get(id);
  if (!terminal) return null;
  const ring = terminal.seqRing;
  if (ring.length === 0) return [];
  if (afterSeq < ring[0].seq - 1) return null; // gap too large — caller must snapshot
  return ring.filter((e) => e.seq > afterSeq);
}
