// POST /api/terminals/[id]/share/auth — exchange the share password for a
// guest session token. Public endpoint; brute-force-limited per IP+terminal.

import type { ShareAuthRequest } from '$lib/types';

import { shareStore, verifyPassword } from '$lib/modules/server/terminal/share-store';
import { json } from '@sveltejs/kit';

import type { RequestHandler } from './$types';

const RATE_LIMIT_WINDOW_MS = 60_000;
const RATE_LIMIT_MAX = 10;

/** Maps "ip:terminalId" -> attempt timestamps (epoch ms). */
const attempts = new Map<string, number[]>();

function checkRateLimit(key: string): boolean {
  const now = Date.now();
  const recent = (attempts.get(key) ?? []).filter((t) => t > now - RATE_LIMIT_WINDOW_MS);
  attempts.set(key, recent);
  if (recent.length >= RATE_LIMIT_MAX) {
    return false;
  }
  recent.push(now);
  return true;
}

// Cleanup stale rate limit entries every 5 minutes
setInterval(() => {
  const cutoff = Date.now() - RATE_LIMIT_WINDOW_MS;
  for (const [key, timestamps] of attempts) {
    const recent = timestamps.filter((t) => t > cutoff);
    if (recent.length === 0) {
      attempts.delete(key);
    } else {
      attempts.set(key, recent);
    }
  }
}, 300_000).unref();

export const POST: RequestHandler = async (event) => {
  const { params, request } = event;

  const share = shareStore.getShare(params.id);
  if (!share) {
    return json({ error: 'Not shared' }, { status: 404 });
  }

  // Behind Cloudflare Tunnel the connecting IP arrives in headers.
  let ip = 'unknown';
  const cfIp = request.headers.get('cf-connecting-ip');
  const fwd = request.headers.get('x-forwarded-for');
  if (cfIp) {
    ip = cfIp;
  } else if (fwd) {
    ip = fwd.split(',')[0].trim();
  } else {
    try {
      ip = event.getClientAddress();
    } catch {
      // Keep 'unknown' — the rate limit still applies per terminal.
    }
  }

  if (!checkRateLimit(`${ip}:${params.id}`)) {
    return json({ error: 'Too many attempts. Try again in a minute.' }, { status: 429 });
  }

  let body: ShareAuthRequest;
  try {
    body = (await request.json()) as ShareAuthRequest;
  } catch {
    return json({ error: 'Invalid JSON' }, { status: 400 });
  }
  if (typeof body.password !== 'string' || !verifyPassword(body.password, share.passwordHash)) {
    return json({ error: 'Invalid password' }, { status: 401 });
  }

  const { expiresAt, token } = shareStore.createSession(params.id);
  return json({ expiresAt, mode: share.mode, token });
};

import type { DecidePayload } from '$lib/types';

import { getRichRequest } from '$lib/modules/server/apn/pending-requests';
import { validateAuth } from '$lib/modules/server/auth';
import { json } from '@sveltejs/kit';

import type { RequestHandler } from './$types';

// GET /api/decide/[requestId]
//
// Returns the full Decide payload (question + options + responseKind +
// tool context) for the iOS Decide screen to render. Called when the
// user taps the notification body (or the "Open in Shooter" action)
// instead of one of the lock-screen quick-tap buttons.
//
// Separated from `/api/response` GET (which is the lightweight polling
// endpoint that returns only the decision) so the rich payload can
// evolve independently and only fires when the iOS screen actually
// needs the full context.
export const GET: RequestHandler = ({ params, request }) => {
  const authErr = validateAuth(request);
  if (authErr) {
    return authErr;
  }

  const requestId = params.requestId;
  if (!requestId) {
    return json({ error: 'requestId path parameter is required' }, { status: 400 });
  }

  const entry = getRichRequest(requestId);
  if (!entry) {
    return json({ error: 'Request not found or expired' }, { status: 404 });
  }

  const payload: DecidePayload = {
    options: entry.options,
    question: entry.question ?? '',
    requestId: entry.requestId,
    responseKind: entry.responseKind,
    toolInput: entry.toolInput,
    toolName: entry.toolName,
  };

  return json(payload);
};

package com.shooter.android

import android.app.NotificationManager
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import okhttp3.Call
import okhttp3.Callback
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import okhttp3.Response
import org.json.JSONObject
import java.io.IOException
import java.util.concurrent.TimeUnit

class PermissionActionReceiver : BroadcastReceiver() {

    private val client = OkHttpClient.Builder()
        .connectTimeout(10, TimeUnit.SECONDS)
        .readTimeout(10, TimeUnit.SECONDS)
        .build()

    override fun onReceive(context: Context, intent: Intent) {
        val requestId = intent.getStringExtra(EXTRA_REQUEST_ID) ?: return
        val notificationId = intent.getIntExtra(EXTRA_NOTIFICATION_ID, -1)

        val decision = when (intent.action) {
            ACTION_ALLOW -> "allow"
            ACTION_DENY -> "deny"
            else -> return
        }

        // Cancel the notification immediately
        if (notificationId != -1) {
            val manager =
                context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            manager.cancel(notificationId)
        }

        val prefs = AppPreferences(context)
        val serverUrl = prefs.serverUrl?.trimEnd('/') ?: return
        val apiKey = prefs.apiKey ?: return

        // Use goAsync() to keep the receiver alive during the network call
        val pendingResult = goAsync()

        val json = JSONObject().apply {
            put("requestId", requestId)
            put("decision", decision)
        }

        val body = json.toString()
            .toRequestBody("application/json; charset=utf-8".toMediaType())

        val request = Request.Builder()
            .url("$serverUrl/api/response")
            .header("Authorization", "Bearer $apiKey")
            .post(body)
            .build()

        sendWithRetry(request, pendingResult, attempt = 1)
    }

    private fun sendWithRetry(
        request: Request,
        pendingResult: PendingResult,
        attempt: Int
    ) {
        client.newCall(request).enqueue(object : Callback {
            override fun onFailure(call: Call, e: IOException) {
                if (attempt < MAX_RETRIES) {
                    val delayMs = INITIAL_BACKOFF_MS * (1L shl (attempt - 1))
                    android.os.Handler(android.os.Looper.getMainLooper()).postDelayed({
                        sendWithRetry(request, pendingResult, attempt + 1)
                    }, delayMs)
                } else {
                    pendingResult.finish()
                }
            }

            override fun onResponse(call: Call, response: Response) {
                val code = response.code
                val isSuccessful = response.isSuccessful
                val body = response.body?.string() ?: ""
                response.close()
                // Server's own "Request not found or expired" 404: first-responder-
                // wins (another device answered) or the request expired. Terminal —
                // do NOT retry. An infrastructure 404 (tunnel down, wrong host, proxy
                // error) has a different body and falls through to retry, so a real
                // decision is not silently dropped. Mirrors NotificationManager (iOS).
                if (code == 404 && body.contains("request not found or expired", ignoreCase = true)) {
                    pendingResult.finish()
                    return
                }
                if (!isSuccessful && attempt < MAX_RETRIES) {
                    val delayMs = INITIAL_BACKOFF_MS * (1L shl (attempt - 1))
                    android.os.Handler(android.os.Looper.getMainLooper()).postDelayed({
                        sendWithRetry(request, pendingResult, attempt + 1)
                    }, delayMs)
                } else {
                    pendingResult.finish()
                }
            }
        })
    }

    companion object {
        private const val MAX_RETRIES = 3
        private const val INITIAL_BACKOFF_MS = 1000L
        const val ACTION_ALLOW = "com.shooter.android.ACTION_ALLOW"
        const val ACTION_DENY = "com.shooter.android.ACTION_DENY"
        const val EXTRA_REQUEST_ID = "extra_request_id"
        const val EXTRA_NOTIFICATION_ID = "extra_notification_id"
    }
}

